  "claim": {
    "component_id": "C024.component",
    "value": "Separated concentrations of trajectories in milestone position, waiting duration, returns to active work and time to first publication are proposed signals to seek.",
    "scope": "Candidate patterns, not reported observations. The mapping does not specify whether separation must be joint across these measures or may occur in individual measures.",
    "provenance": {
      "refs": [
        {
          "source_id": "P014",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span proposes seeking separated trajectory concentrations across the listed dimensions without asserting observed separation or specifying joint separation."
    }
  },
  "signal_basis": {
    "component_id": "C024.signal_basis",
    "value": "Observe onboarding under common conditions, combine milestone events with timed follow-up questions, and record progress–waiting–return transitions. Seek concentrations in the specified trajectory measures while tracking censoring and reporting accounts with no return or incomplete follow-up.",
    "scope": "Prospective descriptive observation within the stated follow-up rules.",
